import{z as r,x as o,o as B,c as D,q as i,j as t,D as A,d as E,s as l,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"纳什均衡与自我对弈的收敛","description":"","frontmatter":{"title":"纳什均衡与自我对弈的收敛","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sgt-nash-convergence.md","filePath":"llm/sgt-nash-convergence.md","lastUpdated":1791413859000}'),p={name:"llm/sgt-nash-convergence.md"};function d(m,a,C,h,g,F){const s=o("Mermaid");return B(),D("div",null,[a[2]||(a[2]=i('<h1 id="纳什均衡与自我对弈的收敛" tabindex="-1">纳什均衡与自我对弈的收敛 <a class="header-anchor" href="#纳什均衡与自我对弈的收敛" aria-label="Permalink to &quot;纳什均衡与自我对弈的收敛&quot;">​</a></h1><div class="epigraph"><p>纳什均衡是一条「无人单方面偏离有利可图」的稳定契约；它是自博弈想要的目的地，但训练动力学并不签到达协议。</p><footer>—— 据 Nash, Non-Cooperative Games, 1951；Daskalakis, Goldberg &amp; Papadimitriou, 2009 整理</footer></div><p><a href="/llm/sgt-game-rl-map">上一课</a>把博弈论对象映射进 RL 词汇，并把「对手是会变的环境」立为本课程的第一性事实，但留了一条尾巴：自博弈的停滞点可以是均衡，也可以是循环。本课把这条尾巴接上——纳什均衡到底是什么，自博弈何时朝它走、哪一步开始不再有保证。后课的 FSP、PSRO 都围绕「均衡能否可靠到达」设计，本课先把目标讲清。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纳什均衡是一组策略 \\(\\sigma=(\\sigma_1,\\ldots,\\sigma_n)\\)，使得每个参与者在其他人的策略固定时，找不到能提高自己效用的单方面偏离：\\(u_i(\\sigma_i&#39;,\\sigma_{-i})\\le u_i(\\sigma)\\) 对一切 \\(\\sigma_i&#39;\\) 成立。它是稳定性的定义，不是最优性的定义——均衡里每个人可能都过得不好，只是谁也动不了。零和两人博弈有更好的刻画：minimax 定理保证双方的最小最大值相等，混合策略均衡就是那对互为最优响应的策略。</p><p><span class="marginnote">「稳定但不最优」用堵车理解最直观：所有人挤同一条路的局面没人愿意先改道（先动的人更慢），可大家都不满意。稳定只说「没人想单独动」，完全不说「大家都过得好」——把均衡读成最优解是最常见的误读。</span></p><p>缺口在于：RL 训练是一个<strong>过程</strong>，均衡是一个<strong>点</strong>。过程趋近点，需要动力学层面的论证。石头剪刀布是标准反例教室：两个渐近学习者的出招比例可以被吸到 \\((1/3,1/3,1/3)\\)，也可能绕着最佳响应圈永远转圈，取决于更新规则的形状。把「训练久就会均衡」当默认，等于当这个分类问题不存在。</p><h3 id="收敛在哪些条件下真" tabindex="-1">收敛在哪些条件下真 <a class="header-anchor" href="#收敛在哪些条件下真" aria-label="Permalink to &quot;收敛在哪些条件下真&quot;">​</a></h3><p>有三类可靠的收敛结果。其一，零和两人规范式博弈，许多无悔更新族在时间平均意义下趋于均衡——博弈论学习理论的主要定理都在这一族里（Cesa-Bianchi 与 Lugosi 2006 有系统整理）。其二，可利用度可以归零：若每轮都对着「当前策略的可利用方向」做最优响应，近似误差可以逐轮压低，这是后课 FSP 与 PSRO 的骨架。其三，特定的势博弈（potential games）有天然的下降量，动力学必然停驻。除这三类之外，一般和博弈的多智能体学习没有公认的收敛保证，Shoham 等人 2007 年那篇「如果多智能体学习是答案，问题是什么」至今仍是对这一领域状态的准确描述。</p><p><span class="marginnote">直觉类比：势博弈像大家一起玩一张「共享海拔图」——任何玩家改善自己的同时，整张图的海拔必定下降一截。正因为有这把所有人对齐的公共尺子，动力学才必然停驻在谷底；一般博弈没有这把尺子，所以会打转。</span></p><p><span class="marginnote">计算侧的坏消息同样硬：两人纳什均衡被证明 PPAD 完全（Chen 与 Deng 2006；一般和见 Daskalakis、Goldberg 与 Papadimitriou 2009）。即便均衡存在唯一，把它算出来也没有已知的多项式算法——「均衡作为可训练目标」先天带复杂度上限。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工程上的正确姿势是把均衡当<strong>审计工具</strong>而不是训练目标。训练时：用带对手池的自博弈（后课）扩大覆盖，避免对着最后一代对手过拟合；审计时：拿冻结的策略去打一组「攻击者」，测可利用度或评测胜率的凹陷。零和可模拟的任务（棋、牌）两类都做得到；语言任务里可利用度算不出来，只能用代理。</p><p>对语言模型，均衡概念已经以另一种方式进场：把 RLHF 的成对比较读成两人博弈，Bradley–Terry 假设隐含传递性，而偏好冲突时传递性破裂，于是有了按博弈论解偏好冲突的<a href="/llm/nash-learning-hf">Nash 学习</a>——那里 Munos 等人 2023 把优化目标从标量奖励改成寻找响应偏好分布的最优策略。本课的贡献是给那类工作一个定位：它们是在「一般和、偏好冲突」的领域里，用均衡替换不存在的标量真值。工程一节留个伏笔：语言任务里可利用度算不出来，审计只能用代理指标——这会在后面的奖励塑形一课变成中心问题。</p>',14)),(B(),t(n,null,{default:A(()=>[l(s,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20SP%5B%22%E8%87%AA%E5%8D%9A%E5%BC%88%E5%8A%A8%E5%8A%9B%E5%AD%A6%22%5D%20--%3E%20Q%7B%22%E5%8D%9A%E5%BC%88%E7%BB%93%E6%9E%84%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E9%9B%B6%E5%92%8C%E4%B8%A4%E4%BA%BA%EF%BC%8C%E6%97%A0%E6%82%94%E6%9B%B4%E6%96%B0%22%7C%20AVG%5B%22%E6%97%B6%E9%97%B4%E5%B9%B3%E5%9D%87%E8%B6%8B%E4%BA%8E%E5%9D%87%E8%A1%A1%22%5D%0A%20%20Q%20--%3E%7C%22%E5%8F%AF%E8%A7%A3%E6%9C%80%E4%BC%98%E5%93%8D%E5%BA%94%22%7C%20EXP%5B%22%E5%8F%AF%E5%88%A9%E7%94%A8%E5%BA%A6%E9%80%90%E8%BD%AE%E4%B8%8B%E9%99%8D%22%5D%0A%20%20Q%20--%3E%7C%22%E4%B8%80%E8%88%AC%E5%92%8C%E4%B8%80%E8%88%AC%E6%9B%B4%E6%96%B0%22%7C%20CYC%5B%22%E5%8F%AF%E8%83%BD%E5%BE%AA%E7%8E%AF%EF%BC%8C%E6%97%A0%E4%BF%9D%E8%AF%81%22%5D%0A%20%20CYC%20--%3E%20AUD%5B%22%E5%9D%87%E8%A1%A1%E5%BD%93%E5%AE%A1%E8%AE%A1%EF%BC%9A%E6%B5%8B%E5%8F%AF%E5%88%A9%E7%94%A8%E6%80%A7%22%5D%0A%20%20AVG%20--%3E%20AUD%0A%20%20EXP%20--%3E%20AUD%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("为什么无悔更新在零和里收敛而一般更新会循环？直觉是：无悔保证"),e("strong",null,"时间平均"),E("策略不被任何固定对手持续剥削，零和结构把这个性质兑换成均衡近似——对手的平均也剥削不了你。但"),e("strong",null,"最后迭代"),E("（last-iterate）可以永远在外圈打转，平均好不等于终点好；用最后一代模型当交付物时，这个差别是实质的。PSRO 之所以解「meta 博弈的均衡」而不是信动力学，就是绕开 last-iterate 问题，把收敛从动力学性质变成求解器的性质。")],-1)),a[5]||(a[5]=e("p",null,"这张分岔图回答的问题是：同一个循环的轨迹，交付「平均」与交付「当前模型」为什么一个有保证、一个没有。",-1)),(B(),t(n,null,{default:A(()=>[l(s,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20LRN%5B%22%E5%8F%8C%E6%96%B9%E6%B8%90%E8%BF%91%E5%AD%A6%E4%B9%A0%E8%80%85%22%5D%20--%3E%20ORB%5B%22%E7%AD%96%E7%95%A5%E8%BD%A8%E8%BF%B9%E7%BB%95%E6%9C%80%E4%BD%B3%E5%93%8D%E5%BA%94%E5%9C%88%E6%89%93%E8%BD%AC%22%5D%0A%20%20ORB%20--%3E%20AVG%5B%22%E6%97%B6%E9%97%B4%E5%B9%B3%E5%9D%87%EF%BC%9A%E8%BD%A8%E8%BF%B9%E9%87%8D%E5%BF%83%E8%B6%8B%E4%BA%8E%E5%9D%87%E8%A1%A1%22%5D%0A%20%20ORB%20--%3E%20LAST%5B%22%E6%9C%80%E5%90%8E%E8%BF%AD%E4%BB%A3%EF%BC%9A%E4%BB%8D%E5%9C%A8%E5%A4%96%E5%9C%88%22%5D%0A%20%20AVG%20--%3E%20DELIV%7B%22%E4%BA%A4%E4%BB%98%E5%93%AA%E4%B8%80%E4%B8%AA%22%7D%0A%20%20LAST%20--%3E%20DELIV%0A%20%20DELIV%20--%3E%7C%22%E5%B9%B3%E5%9D%87%E7%AD%96%E7%95%A5%22%7C%20OK%5B%22%E6%9C%89%E6%94%B6%E6%95%9B%E5%8F%99%E8%BF%B0%E8%83%8C%E4%B9%A6%22%5D%0A%20%20DELIV%20--%3E%7C%22%E5%BD%93%E5%89%8D%E6%A8%A1%E5%9E%8B%22%7C%20RISK%5B%22%E6%97%A0%E4%BF%9D%E8%AF%81%EF%BC%9A%E5%8F%AF%E8%83%BD%E5%81%9C%E5%9C%A8%E5%9C%88%E4%B8%8A%22%5D%0A%20%20RISK%20--%3E%20FIX%5B%22PSRO%EF%BC%9A%E6%94%B9%E7%94%A8%E6%B1%82%E8%A7%A3%E5%99%A8%E8%A7%A3%20meta%20%E5%9D%87%E8%A1%A1%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证明任何定理，只钉边界：均衡存在（Nash 1951）不等于可算（PPAD 完全），可算不等于可学（动力学无保证），可学的时间平均不等于可交付的最后迭代。</p><p><span class="marginnote">为什么重要：四层边界环环相扣，交付物取哪一层决定你继承了哪一层的保证。取「时间平均策略」，手里有定理；取「最后一代 checkpoint」，保证清零。很多自博弈项目翻车，就翻在拿着平均意义的收敛叙述，交付了当前模型。</span> 四层各漏一截，语言模型再补两刀：偏好无零和结构、评测本身可被对策。因此后课的策略没有一个直接「求纳什」：FSP 用平均响应弱化目标，PSRO 把动力学换成求解器，非传递性一课解释为什么对手课程永远做不完——那正是均衡不存在唯一时的日常。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>纳什均衡定义稳定而不定义最优；零和两人另有 minimax 的强结构。</li><li>收敛有三类可靠结果（零和无悔平均、可利用度递减、势博弈），一般和与一般更新不在其列。</li><li>PPAD 完全说明均衡计算本身有复杂度上限，均衡应作审计工具而非训练目标。</li><li>时间平均收敛不保证最后迭代好，交付「当前策略」时这是实质风险。</li><li>语言模型的偏好冲突让均衡以 Nash 学习的形式进场，替换不存在的标量真值。</li><li>出处：Nash 1951；Chen 与 Deng 2006、Daskalakis 等 2009（PPAD）；Cesa-Bianchi 与 Lugosi 2006（无悔与博弈）；Munos 等 2023（Nash 学习）。</li></ul>',5))])}const c=r(p,[["render",d]]);export{P as __pageData,c as default};
